#!/usr/bin/env node
// Regenerates the two AUTOGENERATED appendix sections of
// THIRD_PARTY_LICENSES.md — the full transitive Rust dependency tree
// (from `cargo metadata`) and the npm production dependency tree (from
// `license-checker`) — each grouped by license. Everything else in that
// file (the curated direct-dependency tables and the unrar/ffmpeg/pdfium
// writeups) is maintained by hand and untouched by this script.
//
// Usage: node scripts/update-third-party-licenses.mjs
//
// Run this whenever a direct dependency is added/removed, or a transitive
// dependency's version bump changes its declared license — and before
// cutting a release. Needs network access (npx may need to fetch
// license-checker) and a resolvable Cargo.lock (`--locked`, so it fails
// loudly rather than silently drifting from what's actually vendored).

import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import path from "node:path";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const licensesPath = path.join(repoRoot, "THIRD_PARTY_LICENSES.md");

function run(command) {
  return execSync(command, { cwd: repoRoot, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
}

// --- Rust: cargo metadata -> every crate reachable via a *normal* (non-dev,
// non-build-tool) dependency edge from either workspace member, across
// every platform (cargo metadata's default, unfiltered graph already
// covers all of deny.toml's target triples at once) ---

function rustDependencyGroups() {
  const metadata = JSON.parse(run("cargo metadata --format-version 1 --locked"));
  const nodesById = new Map(metadata.resolve.nodes.map((n) => [n.id, n]));
  const packagesById = new Map(metadata.packages.map((p) => [p.id, p]));
  const workspaceMembers = new Set(metadata.workspace_members);

  const isNormalEdge = (depKinds) => depKinds.some((dk) => dk.kind === null);

  const seen = new Set();
  const included = new Set();
  const stack = [...workspaceMembers];
  while (stack.length > 0) {
    const id = stack.pop();
    if (seen.has(id)) continue;
    seen.add(id);
    if (!workspaceMembers.has(id)) included.add(id);
    const node = nodesById.get(id);
    if (!node) continue;
    for (const dep of node.deps) {
      if (isNormalEdge(dep.dep_kinds ?? [])) stack.push(dep.pkg);
    }
  }

  const byLicense = new Map();
  for (const id of included) {
    const pkg = packagesById.get(id);
    const license = pkg.license ?? "UNKNOWN";
    const entry = `${pkg.name} ${pkg.version}`;
    if (!byLicense.has(license)) byLicense.set(license, new Set());
    byLicense.get(license).add(entry);
  }

  return byLicense;
}

// --- npm: license-checker's production dependency graph, same grouping ---

function npmDependencyGroups() {
  const packageJson = JSON.parse(readFileSync(path.join(repoRoot, "package.json"), "utf8"));
  const ownPackageKey = `${packageJson.name}@${packageJson.version}`;

  const raw = run("npx --yes license-checker --production --json");
  const entries = JSON.parse(raw);

  const byLicense = new Map();
  for (const [key, info] of Object.entries(entries)) {
    if (key === ownPackageKey) continue; // this repo's own (private, unpublished) package
    const licenses = Array.isArray(info.licenses) ? info.licenses.join(" AND ") : info.licenses ?? "UNKNOWN";
    const atIndex = key.lastIndexOf("@");
    const name = key.slice(0, atIndex);
    const version = key.slice(atIndex + 1);
    const entry = `${name} ${version}`;
    if (!byLicense.has(licenses)) byLicense.set(licenses, new Set());
    byLicense.get(licenses).add(entry);
  }

  return byLicense;
}

function formatGroups(byLicense) {
  const groups = [...byLicense.entries()].map(([license, entries]) => [license, [...entries].sort()]);
  // Most-populous license first (ties broken alphabetically), matching how
  // a human skimming for "what's the bulk of this tree" would want it.
  groups.sort((a, b) => b[1].length - a[1].length || a[0].localeCompare(b[0]));
  return groups.map(([license, entries]) => `- **${license}** (${entries.length}): ${entries.join(", ")}`).join("\n\n");
}

function replaceBetweenMarkers(source, markerName, replacement) {
  const begin = `<!-- BEGIN AUTOGENERATED: ${markerName} (run \`node scripts/update-third-party-licenses.mjs\` to refresh) -->`;
  const end = `<!-- END AUTOGENERATED -->`;
  const pattern = new RegExp(`${escapeRegExp(begin)}[\\s\\S]*?${escapeRegExp(end)}`);
  if (!pattern.test(source)) {
    throw new Error(`could not find AUTOGENERATED markers for "${markerName}" in THIRD_PARTY_LICENSES.md`);
  }
  return source.replace(pattern, `${begin}\n\n${replacement}\n\n${end}`);
}

function escapeRegExp(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function totalCrates(byLicense) {
  let total = 0;
  for (const entries of byLicense.values()) total += entries.size;
  return total;
}

const rustGroups = rustDependencyGroups();
const npmGroups = npmDependencyGroups();

const rustSection = `Every crate reachable from a normal (non-dev, non-build-tool) dependency
edge of either workspace member, across all three CI target triples
(\`x86_64-unknown-linux-gnu\`, \`x86_64-pc-windows-msvc\`,
\`x86_64-pc-windows-gnu\`) — ${totalCrates(rustGroups)} crates, generated from \`cargo metadata\`.
Grouped by license; every group here is on \`deny.toml\`'s allow-list.
License texts: [spdx.org/licenses](https://spdx.org/licenses/).

${formatGroups(rustGroups)}`;

const npmSection = `Every package in \`npx license-checker --production\`'s dependency graph
(the packages actually bundled into the frontend by Vite), excluding this
repo's own private, unpublished package. Grouped by license the same way as
the Rust tree above.

${formatGroups(npmGroups)}`;

let content = readFileSync(licensesPath, "utf8");
content = replaceBetweenMarkers(content, "rust-dependency-tree", rustSection);
content = replaceBetweenMarkers(content, "npm-dependency-tree", npmSection);
writeFileSync(licensesPath, content);

console.log(`Rust dependency tree: ${totalCrates(rustGroups)} crates across ${rustGroups.size} license groups`);
console.log(`npm dependency tree: ${totalCrates(npmGroups)} packages across ${npmGroups.size} license groups`);
console.log(`Updated ${path.relative(repoRoot, licensesPath)}`);
